// Helper function to get keywords for a specific job
export function getKeywordsForJob(jobSlug: string): ResumeKeyword[] {
    return resumeKeywords.filter(k =>
        k.jobTitles.includes('all') ||
        k.jobTitles.includes(jobSlug)
    )
}

// Helper function to get keywords by category
export function getKeywordsByCategory(category: ResumeKeyword['category']): ResumeKeyword[] {
    return resumeKeywords.filter(k => k.category === category)
}
